insert into public.training_plans (id, user_id, title, primary_goal, rationale, weeks, starts_on, ends_on, status, targets, generated_by, source_snapshot, created_at) values
  ('plan_20260904', :'demo_user_id'::uuid, '2-week block: 150–175 yd approach', 'Reduce the 2.36 strokes per round currently lost from 150–175 yd approach.', 'Losing 2.36 strokes per round from 150–175 yd approach across 44 shots in 8 rounds. 9-Ball Contact Drill: Solid-contact rate is 70% against a 75% target across 8 sessions. 150-Yard Distance Control: Shots inside the circle is 58% against a 67% target across 5 sessions. Swing analysis flagged a likely transition issue: Club delivery varies between swings. Swing analysis flagged a possible clubface issue: Face appears open through the delivery position.', 2, '2026-09-04', '2026-09-17', 'active', '[{"metric":"Solid-contact rate","skill":"centered_contact","baseline":0.57,"target":0.69,"unit":"%"},{"metric":"Shots inside the circle","skill":"distance_control","baseline":0.42,"target":0.54,"unit":"%"},{"metric":"Shots inside proximity target","skill":"distance_control","baseline":0.38,"target":0.5,"unit":"%"}]'::jsonb, 'rules', '2026-09-04T08:00:00.000Z', '2026-09-04T08:00:00.000Z')
insert into public.plan_sessions (id, plan_id, week, day, title, objective, block_emphasis, duration, drill_ids, is_rest, session_id, status) values
  ('plan_20260904_w1d1', 'plan_20260904', 1, 1, 'Technique: 150–175 yd approach', 'Blocked repetition on centered contact. Same club, same target, immediate feedback on every rep.', 'technical', 45, array['drill_warmup_ladder', 'drill_9_ball_contact', 'drill_half_swing_contact', 'drill_random_approach_challenge']::text[], false, null, 'complete'),
  ('plan_20260904_w1d2', 'plan_20260904', 1, 2, 'Rest', 'Recovery. Optional light putting if you want to touch a club.', 'reflection', 0, '{}', true, null, 'scheduled'),
  ('plan_20260904_w1d3', 'plan_20260904', 1, 3, 'Technique: 150–175 yd approach', 'Blocked repetition on centered contact. Same club, same target, immediate feedback on every rep.', 'technical', 45, array['drill_warmup_ladder', 'drill_9_ball_contact', 'drill_half_swing_contact', 'drill_random_approach_challenge']::text[], false, null, 'complete'),
  ('plan_20260904_w1d4', 'plan_20260904', 1, 4, 'Rest', 'Recovery. Optional light putting if you want to touch a club.', 'reflection', 0, '{}', true, null, 'scheduled'),
  ('plan_20260904_w1d5', 'plan_20260904', 1, 5, 'Skill build: 150–175 yd approach', 'Move centered contact from a rehearsal into a measured skill. Same task, scored.', 'skill', 45, array['drill_warmup_ladder', 'drill_150_distance_control', 'drill_short_iron_dartboard', 'drill_random_approach_challenge']::text[], false, null, 'complete'),
  ('plan_20260904_w1d6', 'plan_20260904', 1, 6, 'Rest', 'Recovery. Optional light putting if you want to touch a club.', 'reflection', 0, '{}', true, null, 'scheduled'),
  ('plan_20260904_w1d7', 'plan_20260904', 1, 7, 'Skill build: 150–175 yd approach', 'Move centered contact from a rehearsal into a measured skill. Same task, scored.', 'skill', 45, array['drill_warmup_ladder', 'drill_150_distance_control', 'drill_short_iron_dartboard', 'drill_random_approach_challenge']::text[], false, null, 'complete'),
  ('plan_20260904_w2d1', 'plan_20260904', 2, 1, 'Random practice', 'Change club and target on every shot. This is where centered contact has to survive contact with a real routine.', 'variable', 45, array['drill_warmup_ladder', 'drill_random_approach_challenge', 'drill_wedge_random_yardage', 'drill_150_distance_control']::text[], false, null, 'complete'),
  ('plan_20260904_w2d2', 'plan_20260904', 2, 2, 'Rest', 'Recovery. Optional light putting if you want to touch a club.', 'reflection', 0, '{}', true, null, 'scheduled'),
  ('plan_20260904_w2d3', 'plan_20260904', 2, 3, 'Random practice', 'Change club and target on every shot. This is where centered contact has to survive contact with a real routine.', 'variable', 45, array['drill_warmup_ladder', 'drill_random_approach_challenge', 'drill_wedge_random_yardage', 'drill_150_distance_control']::text[], false, null, 'complete'),
  ('plan_20260904_w2d4', 'plan_20260904', 2, 4, 'Rest', 'Recovery. Optional light putting if you want to touch a club.', 'reflection', 0, '{}', true, null, 'scheduled'),
  ('plan_20260904_w2d5', 'plan_20260904', 2, 5, 'Pressure block', 'One ball, a consequence, a full routine. Test whether centered contact holds up.', 'pressure', 45, array['drill_warmup_ladder', 'drill_150_distance_control', 'drill_9_ball_contact', 'drill_pitch_landing_zone']::text[], false, null, 'scheduled'),
  ('plan_20260904_w2d6', 'plan_20260904', 2, 6, 'Rest', 'Recovery. Optional light putting if you want to touch a club.', 'reflection', 0, '{}', true, null, 'scheduled'),
  ('plan_20260904_w2d7', 'plan_20260904', 2, 7, 'Assessment', 'Re-test centered contact under one-ball conditions and record the result to compare against the start of the block.', 'pressure', 45, array['drill_warmup_ladder', 'drill_150_distance_control', 'drill_9_ball_contact', 'drill_pitch_landing_zone']::text[], false, null, 'scheduled')
insert into public.plan_adaptations (id, plan_id, created_at, trigger, verdict, summary, changes) values
  ('adapt_1', 'plan_20260904', '2026-09-11T20:00:00.000Z', 'Practice session completed', 'on_track', 'Contact has moved from 61% to 74% against a 75% standard, and the last three rounds show the 150-175 yard losses shrinking. The technical block is doing its job.', array['Reduce the blocked contact drill from 15 to 10 minutes.', 'Add a random approach block with a different yardage on every shot.', 'Keep the transition drill as a warm-up rather than the main block.']::text[])
