insert into public.swing_findings (id, swing_session_id, user_id, category, issue, severity, confidence, certainty, description, why_it_matters, recommended_drill_id, related_skill, source, created_at) values
  ('finding_1', 'swing_1', :'demo_user_id'::uuid, 'transition', 'Club delivery varies between swings', 'high', 0.82, 'likely', 'The change of direction looks rushed, with the arms starting down before the lower body has finished shifting. Delivery position differs noticeably between swings in the same session.', 'An inconsistent delivery makes the face and path relationship different on every swing, which shows up as inconsistent contact and start line.', 'drill_pause_at_top', 'sequencing', 'manual', '2026-08-22T18:10:00.000Z'),
  ('finding_2', 'swing_1', :'demo_user_id'::uuid, 'clubface', 'Face appears open through the delivery position', 'medium', 0.61, 'possible', 'From down the line the face looks open relative to the path midway through the downswing, which fits the right-miss pattern recorded on course.', 'An open face at delivery either produces a right miss or forces a late hand save, and the save is not repeatable under pressure.', 'drill_gate_face_control', 'face_control', 'manual', '2026-08-22T18:12:00.000Z'),
  ('finding_3', 'swing_1', :'demo_user_id'::uuid, 'contact', 'Strike pattern sits toward the toe on mid irons', 'medium', 0.58, 'possible', 'Impact tape from the same session showed most strikes toward the toe, consistent with the contact scores recorded in practice.', 'Toe strikes lose ball speed and turn the face, so distance control suffers even when the swing feels good.', 'drill_9_ball_contact', 'centered_contact', 'manual', '2026-08-22T18:14:00.000Z'),
  ('finding_4', 'swing_2', :'demo_user_id'::uuid, 'setup', 'Ball position drifts back with the driver', 'low', 0.45, 'possible', 'Ball looks closer to centre than to the lead heel on two of the four swings filmed.', 'A back ball position with the driver lowers launch and encourages a steeper attack angle.', null, 'centered_contact', 'manual', '2026-08-23T18:10:00.000Z')
